// Markdown 转 HTML 的完整实现
const inputData = $input.first().json;

// 获取AI生成的报告内容
let markdownContent = inputData.output 
                   || inputData.text 
                   || inputData.response 
                   || inputData.result
                   || inputData.content
                   || JSON.stringify(inputData, null, 2);

console.log('原始 Markdown 内容长度:', markdownContent.length);

// ========================================
// Markdown 转 HTML 转换函数
// ========================================
function markdownToHtml(markdown) {
  let html = markdown;

  // 1. 转义 HTML 特殊字符的函数
  function escapeHtml(text) {
    const map = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#039;'
    };
    return text.replace(/[&<>"']/g, m => map[m]);
  }

  // 2. 处理代码块 (```)
  html = html.replace(/```([\w]*)?\n([\s\S]*?)```/g, function(match, lang, code) {
    return `<pre style="background-color: #2d2d2d; color: #f8f8f2; padding: 15px; border-radius: 5px; overflow-x: auto; margin: 10px 0;"><code class="language-${lang || 'text'}">${escapeHtml(code.trim())}</code></pre>`;
  });

  // 3. 处理行内代码 (`)
  html = html.replace(/`([^`]+)`/g, '<code style="background-color: #f4f4f4; padding: 2px 6px; border-radius: 3px; font-family: monospace; color: #e83e8c; font-size: 0.9em;">$1</code>');

  // 4. 处理标题 - 增大字体
  html = html.replace(/^#### (.*)$/gm, '<h4 style="font-size: 18px; color: #495057; margin-top: 18px; margin-bottom: 8px; font-weight: 600;">$1</h4>');
  html = html.replace(/^### (.*)$/gm, '<h3 style="font-size: 20px; color: #343a40; margin-top: 20px; margin-bottom: 10px; font-weight: 600;">$1</h3>');
  html = html.replace(/^## (.*)$/gm, '<h2 style="font-size: 22px; color: #212529; margin-top: 22px; margin-bottom: 10px; font-weight: 600;">$1</h2>');
  html = html.replace(/^# (.*)$/gm, '<h1 style="font-size: 26px; color: #000; margin-top: 25px; margin-bottom: 12px; font-weight: 700;">$1</h1>');

  // 5. 处理粗体 (**text**)
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong style="font-weight: 600; color: #000;">$1</strong>');

  // 6. 处理斜体 (*text*)
  html = html.replace(/(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g, '<em>$1</em>');

  // 7. 处理链接 [text](url)
  html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="color: #007bff; text-decoration: none;">$1</a>');

  // 8. 处理分隔线
  html = html.replace(/^---+$/gm, '<hr style="border: 0; border-top: 2px solid #dee2e6; margin: 15px 0;">');
  html = html.replace(/^━━━.*$/gm, '<hr style="border: 0; border-top: 2px solid #667eea; margin: 15px 0;">');

  // 9. 处理无序列表
  html = html.replace(/^[\-\*\+] (.+)$/gm, '<li style="margin-bottom: 5px;">$1</li>');
  // 包裹连续的 <li> 标签
  html = html.replace(/(<li[^>]*>.*?<\/li>\n?)+/gs, match => {
    return '<ul style="margin: 8px 0; padding-left: 25px; line-height: 1.5;">' + match + '</ul>';
  });

  // 10. 处理有序列表
  html = html.replace(/^\d+\.\s(.+)$/gm, '<li style="margin-bottom: 5px;">$1</li>');

  // 11. 处理段落 - 减小行距
  const paragraphs = html.split(/\n\n+/);
  html = paragraphs.map(para => {
    para = para.trim();
    if (!para) return '';

    // 如果已经是HTML标签开头，不包装
    if (para.match(/^<(h[1-6]|ul|ol|pre|hr|blockquote)/)) {
      return para;
    }

    return `<p style="margin: 8px 0; line-height: 1.5;">${para}</p>`;
  }).join('\n');

  // 12. 处理单换行为 <br> - 减少额外空行
  html = html.replace(/\n/g, '<br>');

  return html;
}

// 转换 Markdown 为 HTML
const htmlContent = markdownToHtml(markdownContent);

console.log('转换后的 HTML 长度:', htmlContent.length);

// 返回结果
return [
  {
    json: {
      ...inputData,
      markdownContent: markdownContent,
      htmlContent: htmlContent,
      conversionSuccess: true
    }
  }
];

